190: ## 4. Conclusion & Proposed Code Implementation
191: 
192: ### 4.1 Proposed `src/services/redactor.ts`
193: The complete, production-ready replacement for `src/services/redactor.ts`:
194: 
195: ```ts
196: import type { LoadOptions, Redact, RedactLabel } from "@desert-ant-labs/redact/native";
197: import { Redact as NativeRedact } from "@desert-ant-labs/redact/native";
198: import type { PiiCategory, PiiRule, RedactionResult, RedactorConfig } from "../types.js";
199: import { defaultRules } from "../rules/default-rules.js";
200: 
201: /** Configuration options for RedactorService initialization. */
202: export interface RedactorServiceOptions {
203:   /** Optional options passed to Redact.load(...) (e.g. offline directory or cacheRoot). */
204:   loadOptions?: LoadOptions;
205:   /** Optional pre-instantiated or mock Redact engine (useful for unit testing). */
206:   redactInstance?: Redact;
207: }
208: 
209: export class RedactorService {
210:   private rules: Map<string, PiiRule>;
211:   private config: RedactorConfig;
212:   private loadOptions?: LoadOptions;
213:   private instance: Redact | null = null;
214:   private initPromise: Promise<Redact> | null = null;
215: 
216:   constructor(
217:     customRules: PiiRule[] = [],
218:     initialConfig?: Partial<RedactorConfig>,
219:     options?: RedactorServiceOptions | LoadOptions
220:   ) {
221:     this.rules = new Map();
222:     for (const rule of [...defaultRules, ...customRules]) {
223:       this.rules.set(rule.id, { ...rule });
224:     }
225: 
226:     this.config = {
227:       enabled: true,
228:       maskUserInputs: true,
229:       maskToolResults: true,
230:       maskContextMessages: true,
231:       notifyOnRedact: true,
232:       ...initialConfig,
233:     };
234: 
235:     if (options) {
236:       if ("redactInstance" in options || "loadOptions" in options) {
237:         const svcOpts = options as RedactorServiceOptions;
238:         this.loadOptions = svcOpts.loadOptions;
239:         if (svcOpts.redactInstance) {
240:           this.instance = svcOpts.redactInstance;
241:         }
242:       } else {
243:         this.loadOptions = options as LoadOptions;
244:       }
245:     }
246:   }
247: 
248:   /** Returns whether redaction is globally enabled. */
249:   public isEnabled(): boolean {
250:     return this.config.enabled;
251:   }
252: 
253:   /** Globally enable or disable redaction. */
254:   public setEnabled(enabled: boolean): void {
255:     this.config.enabled = enabled;
256:   }
257: 
258:   /** Returns read-only view of redactor configuration. */
259:   public getConfig(): Readonly<RedactorConfig> {
260:     return this.config;
261:   }
262: 
263:   /** Returns all registered rules (both native model labels and overlay rules). */
264:   public getRules(): PiiRule[] {
265:     return Array.from(this.rules.values());
266:   }
267: 
268:   /**
269:    * Toggles an individual rule by id (case and format insensitive).
270:    * Returns the new enabled state, or false if the rule was not found.
271:    */
272:   public toggleRule(ruleId: string, enabled?: boolean): boolean {
273:     const rule =
274:       this.rules.get(ruleId) ??
275:       this.rules.get(ruleId.toLowerCase()) ??
276:       this.rules.get(ruleId.toUpperCase()) ??
277:       this.rules.get(ruleId.replace(/_/g, "-").toLowerCase());
278: 
279:     if (!rule) return false;
280:     rule.enabled = enabled ?? !rule.enabled;
281:     return rule.enabled;
282:   }
283: 
284:   /**
285:    * Returns the initialized native Redact instance, loading it on demand if necessary.
286:    * Concurrent calls await the same initialization promise.
287:    */
288:   public async getRedactInstance(): Promise<Redact> {
289:     if (this.instance) {
290:       return this.instance;
291:     }
292:     if (!this.initPromise) {
293:       this.initPromise = (async () => {
294:         try {
295:           const inst = await NativeRedact.load(this.loadOptions);
296:           this.instance = inst;
297:           return inst;
298:         } catch (error) {
299:           this.initPromise = null;
300:           throw error;
301:         }
302:       })();
303:     }
304:     return this.initPromise;
305:   }
306: 
307:   /** Eagerly initializes the native model. */
308:   public async init(): Promise<void> {
309:     await this.getRedactInstance();
310:   }
311: 
312:   /** Releases native engine resources. Safe to call multiple times. */
313:   public dispose(): void {
314:     if (this.instance) {
315:       this.instance.dispose();
316:       this.instance = null;
317:     }
318:     this.initPromise = null;
319:   }
320: 
321:   /**
322:    * Asynchronously redacts sensitive data (PII and API secrets) from the input text.
323:    */
324:   public async redact(text: string): Promise<RedactionResult> {
325:     if (!this.config.enabled || !text || typeof text !== "string") {
326:       return {
327:         text: text ?? "",
328:         hasRedactions: false,
329:         count: 0,
330:         redactions: [],
331:       };
332:     }
333: 
334:     let currentText = text;
335:     const allRedactions: RedactionResult["redactions"] = [];
336: 
337:     // 1. Partition active rules into regex overlay rules vs native model labels
338:     const activeRegexRules: PiiRule[] = [];
339:     const activeNativeLabels: string[] = [];
340: 
341:     for (const rule of this.rules.values()) {
342:       if (!rule.enabled) continue;
343: 
344:       if (rule.pattern) {
345:         activeRegexRules.push(rule);
346:       } else {
347:         const label =
348:           (rule as { nativeLabel?: string }).nativeLabel ??
349:           rule.id.toUpperCase().replace(/-/g, "_");
350:         activeNativeLabels.push(label);
351:       }
352:     }
353: 
354:     // 2. Phase 1: Apply regex overlay rules (API keys, custom secrets)
355:     for (const rule of activeRegexRules) {
356:       const flags = rule.pattern!.flags.includes("g")
357:         ? rule.pattern!.flags
358:         : `${rule.pattern!.flags}g`;
359:       const regex = new RegExp(rule.pattern!.source, flags);
360: 
361:       currentText = currentText.replace(regex, (match) => {
362:         const masked = rule.mask ? rule.mask(match) : `[REDACTED:${rule.id.toUpperCase()}]`;
363:         allRedactions.push({
364:           category: rule.category,
365:           ruleId: rule.id,
366:           original: match,
367:           masked,
368:         });
369:         return masked;
370:       });
371:     }
372: 
373:     // 3. Phase 2: Apply native ML inference if any native labels are active
374:     // CRITICAL: If activeNativeLabels is empty, do NOT pass { labels: [] }, as
375:     // @desert-ant-labs/redact treats an empty array as ALL labels enabled.
376:     let restoreHelper: ((processed: string) => string) | undefined;
377: 
378:     if (activeNativeLabels.length > 0) {
379:       const redactInstance = await this.getRedactInstance();
380:       const nativeResult = await redactInstance.redaction(currentText, {
381:         labels: activeNativeLabels as Iterable<RedactLabel>,
382:       });
383: 
384:       currentText = nativeResult.redactedText;
385:       restoreHelper = (p: string) => nativeResult.restore(p);
386: 
387:       for (const item of nativeResult.items) {
388:         const matchingRule = this.findRuleForNativeLabel(item.label);
389:         allRedactions.push({
390:           category: matchingRule?.category ?? this.mapNativeLabelToCategory(item.label),
391:           ruleId: matchingRule?.id ?? item.label.toLowerCase(),
392:           original: item.original,
393:           masked: item.placeholder,
394:         });
395:       }
396:     }
397: 
398:     return {
399:       text: currentText,
400:       hasRedactions: allRedactions.length > 0,
401:       count: allRedactions.length,
402:       redactions: allRedactions,
403:       restore: restoreHelper,
404:     };
405:   }
406: 
407:   private findRuleForNativeLabel(label: string): PiiRule | undefined {
408:     const upper = label.toUpperCase();
409:     for (const rule of this.rules.values()) {
410:       const nativeLabel = (rule as { nativeLabel?: string }).nativeLabel;
411:       if (nativeLabel && nativeLabel.toUpperCase() === upper) {
412:         return rule;
413:       }
414:       if (rule.id.toUpperCase().replace(/-/g, "_") === upper) {
415:         return rule;
416:       }
417:     }
418:     return undefined;
419:   }
420: 
421:   private mapNativeLabelToCategory(label: string): PiiCategory {
422:     const upper = label.toUpperCase();
423:     switch (upper) {
424:       case "EMAIL":
425:         return "email";
426:       case "PHONE":
427:         return "phone";
428:       case "IP_ADDRESS":
429:         return "ip";
430:       case "CREDIT_CARD":
431:         return "credit-card";
432:       default:
433:         return upper as PiiCategory;
434:     }
435:   }
436: }
